	int unk_0xD0;
	int unk_0xD4;
	int unk_0xD8;
	int unk_0xDC;

	int unk_0xE0;
	int unk_0xE4;
	int unk_0xE8;
	int unk_0xEC;

	int unk_0xF0;
	int unk_0xF4;
	int unk_0xF8;
	int unk_0xFC;
} SceKernelThreadStatus;

typedef struct SceKernelThreadFloatRegister { // size is 0x100
	union {
		unsigned int s_reg_i[0x40];
		float        s_reg_f[0x40];
		uint64_t     d_reg_i[0x20];
		double       d_reg_f[0x20];
